class Animal {
  constructor(name) { this.name = name; }
  speak() { return "..."; }
}
class Dog extends Animal {
  bark() { return `${this.name} says woof`; }
}
const d = new Dog("Rex");
console.log(d.bark());
console.log(d instanceof Animal);

