exercises.solution:
class Animal { speak() { return "..."; } }
class Dog extends Animal { speak() { return "woof"; } }
class Cat extends Animal { speak() { return "meow"; } }
function makeAllSpeak(animals) {
  return animals.map(a => a.speak());
}
console.log(makeAllSpeak([new Dog(), new Cat()]));
